class Solution {
  public int collectTheCoins(int[] coins, int[][] edges) {
    int n = coins.length;
    List<Integer>[] graph = new List[n];
    int[] degree = new int[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
      graph[e[0]].add(e[1]);
      graph[e[1]].add(e[0]);
      degree[e[0]]++;
      degree[e[1]]++;
    }
    boolean[] alive = new boolean[n];
    Arrays.fill(alive, true);
    // drop leaves without coins until every leaf holds a coin
    Deque<Integer> queue = new ArrayDeque<>();
    for (int i = 0; i < n; i++) if (degree[i] <= 1 && coins[i] == 0) queue.add(i);
    while (!queue.isEmpty()) {
      int u = queue.poll();
      if (!alive[u]) continue;
      alive[u] = false;
      for (int v : graph[u]) {
        if (alive[v] && --degree[v] <= 1 && coins[v] == 0) queue.add(v);
      }
    }
    // a coin within distance 2 can be collected from afar: shave off two layers of leaves
    for (int layer = 0; layer < 2; layer++) {
      List<Integer> leaves = new ArrayList<>();
      for (int i = 0; i < n; i++) if (alive[i] && degree[i] <= 1) leaves.add(i);
      for (int u : leaves) alive[u] = false;
      for (int u : leaves) for (int v : graph[u]) if (alive[v]) degree[v]--;
    }
    int remaining = 0;
    for (boolean a : alive) if (a) remaining++;
    return remaining <= 1 ? 0 : 2 * (remaining - 1);
  }
}
